-- Immutable archive data. Snapshots are copies, so live people/classes remain editable.
ALTER TABLE ArchiveSnapshot ADD COLUMN capturedAt DATETIME;
CREATE TRIGGER archive_result_reparent BEFORE UPDATE ON StudentResult WHEN NEW.quizId IS NOT OLD.quizId AND (EXISTS(SELECT 1 FROM Quiz WHERE id=NEW.quizId AND status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow WHERE entityType='quiz' AND entityId=NEW.quizId)) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_result_stamp BEFORE UPDATE ON StudentResult WHEN OLD.academicYear IS NULL AND NEW.academicYear IS NOT NULL AND (EXISTS(SELECT 1 FROM Quiz WHERE id=OLD.quizId AND status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow WHERE entityType='result' AND entityId=OLD.id)) AND NOT EXISTS(SELECT 1 FROM ArchiveSnapshotRow r JOIN ArchiveSnapshot s ON s.id=r.snapshotId JOIN AcademicYear y ON y.id=s.academicYearId WHERE r.entityType='result' AND r.entityId=OLD.id AND s.status='verified' AND s.label=NEW.academicYear AND y.status='active') BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_quiz_transition BEFORE UPDATE ON Quiz WHEN NEW.status='archived' AND EXISTS(SELECT 1 FROM ArchiveSnapshotRow WHERE entityType='quiz' AND entityId=OLD.id) AND NOT EXISTS(SELECT 1 FROM ArchiveSnapshotRow r JOIN ArchiveSnapshot s ON s.id=r.snapshotId JOIN AcademicYear y ON y.id=s.academicYearId WHERE r.entityType='quiz' AND r.entityId=OLD.id AND s.status='verified' AND s.label=NEW.academicYear AND y.status='active') BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_answer_question_insert BEFORE INSERT ON SurveyAnswer WHEN EXISTS(SELECT 1 FROM Question q JOIN Quiz z ON z.id=q.quizId WHERE q.id=NEW.questionId AND (z.status='archived' OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow WHERE entityType='quiz' AND entityId=z.id))) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_answer_question_update BEFORE UPDATE ON SurveyAnswer WHEN EXISTS(SELECT 1 FROM Question q JOIN Quiz z ON z.id=q.quizId WHERE q.id IN (OLD.questionId,NEW.questionId) AND (z.status='archived' OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow WHERE entityType='quiz' AND entityId=z.id))) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_quiz_update BEFORE UPDATE ON Quiz WHEN OLD.status='archived' OR (EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD.id) AND NOT(OLD.status<>'archived' AND NEW.status='archived' AND NEW."id" IS OLD."id" AND NEW."title" IS OLD."title" AND NEW."description" IS OLD."description" AND NEW."difficulty" IS OLD."difficulty" AND NEW."timeLimit" IS OLD."timeLimit" AND NEW."shuffleQuestions" IS OLD."shuffleQuestions" AND NEW."contentType" IS OLD."contentType" AND NEW."publishedAt" IS OLD."publishedAt" AND NEW."audienceSize" IS OLD."audienceSize" AND NEW."createdAt" IS OLD."createdAt" AND NEW."categoryId" IS OLD."categoryId" AND NEW."createdBy" IS OLD."createdBy" AND EXISTS(SELECT 1 FROM ArchiveSnapshotRow r JOIN ArchiveSnapshot s ON s.id=r.snapshotId WHERE r.entityType='quiz' AND r.entityId=OLD.id AND s.status='verified' AND NEW.academicYear=s.label))) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_quiz_delete BEFORE DELETE ON Quiz WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD.id AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD.id)) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_question_insert BEFORE INSERT ON "Question" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=NEW."quizId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=NEW."quizId")) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_question_update BEFORE UPDATE ON "Question" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD."quizId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD."quizId")) OR (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=NEW."quizId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=NEW."quizId")) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_question_delete BEFORE DELETE ON "Question" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD."quizId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD."quizId")) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_surveysubmission_insert BEFORE INSERT ON "SurveySubmission" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=NEW."surveyId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=NEW."surveyId")) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_surveysubmission_update BEFORE UPDATE ON "SurveySubmission" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD."surveyId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD."surveyId")) OR (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=NEW."surveyId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=NEW."surveyId")) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_surveysubmission_delete BEFORE DELETE ON "SurveySubmission" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD."surveyId" AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD."surveyId")) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_survey_answer_insert BEFORE INSERT ON SurveyAnswer WHEN EXISTS(SELECT 1 FROM SurveySubmission s WHERE s.id=NEW.submissionId AND (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=s.surveyId AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=s.surveyId))) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_survey_answer_update BEFORE UPDATE ON SurveyAnswer WHEN EXISTS(SELECT 1 FROM SurveySubmission s WHERE s.id=OLD.submissionId AND (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=s.surveyId AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=s.surveyId))) OR EXISTS(SELECT 1 FROM SurveySubmission s WHERE s.id=NEW.submissionId AND (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=s.surveyId AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=s.surveyId))) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_survey_answer_delete BEFORE DELETE ON SurveyAnswer WHEN EXISTS(SELECT 1 FROM SurveySubmission s WHERE s.id=OLD.submissionId AND (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=s.surveyId AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=s.surveyId))) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_result_update BEFORE UPDATE ON StudentResult WHEN (OLD.academicYear IS NOT NULL OR (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD.quizId AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD.quizId)) OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='result' AND r.entityId=OLD.id)) AND NOT(OLD.academicYear IS NULL AND NEW.academicYear IS NOT NULL AND NEW."id" IS OLD."id" AND NEW."studentId" IS OLD."studentId" AND NEW."quizId" IS OLD."quizId" AND NEW."status" IS OLD."status" AND NEW."answers" IS OLD."answers" AND NEW."score" IS OLD."score" AND NEW."correctAnswersCount" IS OLD."correctAnswersCount" AND NEW."totalQuestions" IS OLD."totalQuestions" AND NEW."timeTaken" IS OLD."timeTaken" AND NEW."startedAt" IS OLD."startedAt" AND NEW."submittedAt" IS OLD."submittedAt" AND NEW."completedAt" IS OLD."completedAt" AND NEW.academicYear=(SELECT academicYear FROM Quiz WHERE id=OLD.quizId)) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_result_delete BEFORE DELETE ON StudentResult WHEN OLD.academicYear IS NOT NULL OR (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD.quizId AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD.quizId)) OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='result' AND r.entityId=OLD.id) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_result_insert BEFORE INSERT ON StudentResult WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=NEW.quizId AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=NEW.quizId)) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_class_quiz_insert BEFORE INSERT ON "_ClassQuizzes" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=NEW.B AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=NEW.B)) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_class_quiz_update BEFORE UPDATE ON "_ClassQuizzes" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD.B AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD.B)) OR (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=NEW.B AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=NEW.B)) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_class_quiz_delete BEFORE DELETE ON "_ClassQuizzes" WHEN (EXISTS(SELECT 1 FROM Quiz q WHERE q.id=OLD.B AND q.status='archived') OR EXISTS(SELECT 1 FROM ArchiveSnapshotRow r WHERE r.entityType='quiz' AND r.entityId=OLD.B)) BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_snapshot_row_update BEFORE UPDATE ON ArchiveSnapshotRow BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_snapshot_row_delete BEFORE DELETE ON ArchiveSnapshotRow BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_snapshot_row_insert BEFORE INSERT ON ArchiveSnapshotRow WHEN (SELECT status FROM ArchiveSnapshot WHERE id=NEW.snapshotId) NOT IN ('queued','capturing') BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_completed_snapshot_update BEFORE UPDATE ON ArchiveSnapshot WHEN OLD.status='completed' BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_closed_year_update BEFORE UPDATE ON AcademicYear WHEN OLD.status='closed' BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_completed_snapshot_delete BEFORE DELETE ON ArchiveSnapshot WHEN OLD.status='completed' BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
CREATE TRIGGER archive_closed_year_delete BEFORE DELETE ON AcademicYear WHEN OLD.status='closed' BEGIN SELECT RAISE(ABORT,'ARCHIVE_READ_ONLY'); END;
